//! Guardrail: the product name and version are defined in a few places (AGENTS.md "Repository
//! identity") and must never drift apart.
//!
//! - Version: `core/pyproject.toml` is the source of truth (one shared version number); the
//!   app's copy is `version` in this crate's `Cargo.toml`, which Tauri reads.
//! - Display name: `productName` in `tauri.conf.json` is canonical; the popup window title and
//!   `PRODUCT_NAME` in `app/src/product.ts` must equal it. `product.ts` is generated by
//!   `npm run gen` and drift-checked by `npm run lint:gen`; this test is a second guard.

use std::{fs, path::Path};

use serde_json::Value;

fn read(relative: &str) -> String {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join(relative);
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

/// Plain line match on purpose: the shell never parses TOML (app/src-tauri/AGENTS.md).
fn core_version() -> String {
    read("../../core/pyproject.toml")
        .lines()
        .find_map(|line| line.trim().strip_prefix("version = "))
        .map(|value| value.trim_matches('"').to_owned())
        .expect("core/pyproject.toml has a `version = \"...\"` line")
}

fn tauri_config() -> Value {
    serde_json::from_str(&read("tauri.conf.json")).expect("tauri.conf.json is valid JSON")
}

fn product_name() -> String {
    tauri_config()["productName"]
        .as_str()
        .expect("tauri.conf.json has a productName")
        .to_owned()
}

#[test]
fn app_version_matches_the_core_version() {
    assert_eq!(env!("CARGO_PKG_VERSION"), core_version());
}

#[test]
fn popup_window_title_is_the_product_name() {
    let config = tauri_config();
    let windows = config["app"]["windows"]
        .as_array()
        .expect("tauri.conf.json declares windows");
    for window in windows {
        assert_eq!(
            window["title"].as_str(),
            Some(product_name().as_str()),
            "window `{}` title",
            window["label"]
        );
    }
}

#[test]
fn ui_product_name_constant_is_the_product_name() {
    let expected = format!("export const PRODUCT_NAME = \"{}\";", product_name());
    let source = read("../src/product.ts");
    assert!(
        source.lines().any(|line| line.trim() == expected),
        "app/src/product.ts must contain `{expected}`"
    );
}
